<?php

# @autogenerated
declare(strict_types=1);

namespace Civi\Lughauth\Features\Access\TrustedClient\Domain\ValueObject\Accessor;

use Civi\Lughauth\Features\Access\TrustedClient\Domain\ValueObject\TrustedClientVersionVO;

trait TrustedClientVersionAccessor
{
    private ?TrustedClientVersionVO $_version = null;
    public function getVersion(): ?int
    {
        return $this->_version?->value();
    }
    public function version(): ?TrustedClientVersionVO
    {
        return $this->_version;
    }
    public function isVersionChanged(?self $original = null): bool
    {
        return null !== $this->_version && !$this->_version->equals($original?->_version);
    }
    public function withVersion(TrustedClientVersionVO|int|null $version): self
    {
        $copy = clone $this;
        $copy->_version = TrustedClientVersionVO::from($version);
        return $copy;
    }
}
